VALUES ('naver-97305add674f', '꿈 너머 꿈! 또 하나의 꿈을 만들어가는 교육가 고도원을 만나다!', '<p>''꿈 너머 꿈''이라는 말을 하고 있는데, 지금까지 ''깊은산속 옹달샘''이 꿈이라고 하면 그 다음 꿈은 무엇일까 생각했죠. 청소년 수련원과 BDS(꿈너머꿈 국제학교)가 앞으로 저의 꿈이자 비전입니다. 그 동안 ''깊은산속…</p><p><strong>출처</strong> · 한국강사신문 · 2019-09-09</p><p><a href="http://www.lecturernews.com/news/articleView.html?idxno=24963" target="_blank" rel="noopener noreferrer">원문 기사 보기 →</a></p>', '''꿈 너머 꿈''이라는 말을 하고 있는데, 지금까지 ''깊은산속 옹달샘''이 꿈이라고 하면 그 다음 꿈은 무엇일까 생각했죠. 청소년 수련원과 BDS(꿈너머꿈 국제학교)가 앞으로 저의 꿈이자 비전입니다. 그 동안 ''깊은산속…', NULL, 'news', '한국강사신문', 1, '2019-09-09 08:51:00', '2019-09-09 08:51:00');
INSERT OR IGNORE INTO posts
