VALUES ('naver-2ec6e96c3429', '“미네르바 바칼로레아 도입, 지혜 배우는 학교 만들 것”', '<p>미네르바 바칼로레아 과정은 올해 개교한 기숙형 국제 대안학교인 ‘꿈너머꿈(BDS) 글로벌리더 스콜라스’에... “학생들을 만나면 ‘꿈 너머 꿈’을 묻습니다. 꿈을 이룬다면 그다음엔 어떤 일을 하고 싶으냐는 거예요.…</p><p><strong>출처</strong> · 조선일보 · 2020-12-21</p><p><a href="https://www.chosun.com/special/future100/fu_general/2020/12/21/CWIYZQ6QJFHCXMGX35E5BMK3UE/" target="_blank" rel="noopener noreferrer">원문 기사 보기 →</a></p>', '미네르바 바칼로레아 과정은 올해 개교한 기숙형 국제 대안학교인 ‘꿈너머꿈(BDS) 글로벌리더 스콜라스’에... “학생들을 만나면 ‘꿈 너머 꿈’을 묻습니다. 꿈을 이룬다면 그다음엔 어떤 일을 하고 싶으냐는 거예요.…', NULL, 'news', '조선일보', 1, '2020-12-21 03:10:00', '2020-12-21 03:10:00');
INSERT OR IGNORE INTO posts
